      font-size: 14px;
      font-weight: 500;
      transition: color var(--transition);
    }

    .nav-links a:hover { color: var(--white); }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn-sign-in {
      color: var(--gray-300);
      font-size: 14px;
      font-weight: 500;
      padding: 8px 16px;
