      color: var(--white);
      padding: 8px;
    }

    /* ========== HERO ========== */
    .hero {
      background: linear-gradient(160deg, #0B0E11 0%, #141820 40%, #1a1230 70%, #0B0E11 100%);
      padding: 140px 0 80px;
      position: relative;
      overflow: hidden;
