    .hero::before {
      content: '';
      position: absolute;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(86, 32, 193, 0.15) 0%, transparent 70%);
      top: -100px;
      right: -200px;
      pointer-events: none;
