      background: var(--black);
      padding: 64px 0 32px;
      color: var(--gray-400);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
      margin-bottom: 48px;
    }

    .footer-col h5 {
