    ];

    const courseGrid = document.getElementById("courseGrid");

    function renderCourses(category) {
      const filtered = category === "featured"
        ? allCourses.filter(c => c.categories.includes("featured"))
        : allCourses.filter(c => c.categories.includes(category));

      const courses = filtered.length > 0 ? filtered : allCourses.slice(0, 4);

      courseGrid.style.opacity = "0";
      courseGrid.style.transform = "translateY(8px)";

      setTimeout(() => {
        courseGrid.innerHTML = courses.map(c => `
          <div class="course-card">
            <div class="course-thumb">
              <div class="course-thumb-inner ${c.theme}">
                ${c.title.split(":")[0].split(" ").slice(0, 2).join(" ")}
              </div>
            </div>
            <div class="course-info">
              <div class="course-title">${c.title}</div>
              <div class="course-instructor">${c.instructor}</div>
              <div class="course-meta">
                <span>
                  <svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/></svg>
                  ${c.students}
                </span>
                <span>
                  <svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                  ${c.duration}
                </span>
              </div>
            </div>
          </div>
        `).join("");

        requestAnimationFrame(() => {
          courseGrid.style.transition = "opacity 0.3s ease, transform 0.3s ease";
          courseGrid.style.opacity = "1";
          courseGrid.style.transform = "translateY(0)";
        });
      }, 150);
    }

    document.querySelectorAll(".course-tab").forEach(tab => {
      tab.addEventListener("click", () => {
        document.querySelectorAll(".course-tab").forEach(t => t.classList.remove("active"));
        tab.classList.add("active");
        renderCourses(tab.dataset.category);
      });
    });

    renderCourses("featured");

    // ===== FAQ Accordion =====
    document.querySelectorAll(".faq-question").forEach(btn => {
      btn.addEventListener("click", () => {
        const item = btn.parentElement;
        const isOpen = item.classList.contains("active");

        document.querySelectorAll(".faq-item").forEach(i => {
          i.classList.remove("active");
          i.querySelector(".faq-question").setAttribute("aria-expanded", "false");
        });

        if (!isOpen) {
          item.classList.add("active");
          btn.setAttribute("aria-expanded", "true");
        }
      });
    });

    // ===== Teacher Carousel =====
    const carousel = document.getElementById("teacherCarousel");
    const prevBtn = document.getElementById("carouselPrev");
    const nextBtn = document.getElementById("carouselNext");

    prevBtn.addEventListener("click", () => {
      carousel.scrollBy({ left: -280, behavior: "smooth" });
    });

    nextBtn.addEventListener("click", () => {
      carousel.scrollBy({ left: 280, behavior: "smooth" });
    });
